-- Datos iniciales de TechFix.AI: cuenta ADMIN, inventario de repuestos, categorías contables y plan PCGE.
-- Requiere una base creada con sql/esquema-vacio-produccion.sql. Ver sql/README.md.
--
-- La contraseña del ADMIN no se guarda en este archivo. Antes de ejecutarlo, en la MISMA sesión,
-- fija el hash bcrypt de la contraseña elegida (y, si quieres, el correo):
--
--   SET techfix.admin_password_hash = '$2b$12$...';      -- obligatorio
--   SET techfix.admin_email = 'admin@techfix.pe';        -- opcional (valor por defecto)
--
-- Genera el hash desde el backend con:
--   python -c "import getpass; from app.accounts.security import hash_password; print(hash_password(getpass.getpass('Contraseña: ')))"
--
-- Todo corre en una transacción: si algo falla, no se guarda nada. Se puede repetir sin duplicar:
-- no recrea al ADMIN si su correo ya existe, no pisa repuestos existentes y el PCGE es idempotente.
BEGIN;

-- ---------------------------------------------------------------------------------------------
-- 1. Cuenta ADMIN por defecto
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE
  v_email TEXT := lower(btrim(coalesce(nullif(current_setting('techfix.admin_email', true), ''), 'admin@techfix.pe')));
  v_hash TEXT := btrim(coalesce(current_setting('techfix.admin_password_hash', true), ''));
BEGIN
  IF EXISTS (SELECT 1 FROM public.users WHERE lower(email) = v_email) THEN
    RAISE NOTICE 'La cuenta % ya existe; no se modifica.', v_email;
    RETURN;
  END IF;
  IF v_hash !~ '^\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53}$' THEN
    RAISE EXCEPTION 'Falta el hash bcrypt de la contraseña del ADMIN. Ejecuta antes: SET techfix.admin_password_hash = ''<hash bcrypt>''; (ver cabecera del archivo)';
  END IF;
  VALUES (v_email, '+51900000000', v_hash, 'Administrador', 'TechFix', 'ADMIN', TRUE);
  RAISE NOTICE 'Cuenta ADMIN % creada.', v_email;
END $$;

