-- ===== INVENTARIO ADICIONAL =====
-- INVENTARIO AMPLIADO PARA PRUEBAS DEL SISTEMA MULTIAGENTE
-- Los precios y stocks de este script son datos sintéticos de demostración, no precios de mercado.
-- En repuestos de laptop se exige validar modelo/número de parte antes de vender.
ON CONFLICT (code) DO NOTHING;

-- Saldo inicial SYSTEM por artículo, como exige la trazabilidad de inventario: la historia de cada
-- repuesto empieza con su stock de carga. El índice ux_inventory_movements_system_opening impide duplicarlo.
     stock_before, stock_after, actor_user_id, actor_kind, reason)
SELECT p.id, 'OPENING_BALANCE', p.code, p.name, p.current_stock, 0, p.current_stock, NULL, 'SYSTEM',
       'Saldo inicial de la carga de datos'
  FROM public.spare_parts p
 WHERE NOT EXISTS (
   SELECT 1 FROM public.inventory_movements m
    WHERE m.spare_part_id = p.id AND m.movement_type = 'OPENING_BALANCE'
 )
 ORDER BY p.id;

-- ---------------------------------------------------------------------------------------------
-- 3. Categorías internas de asientos contables (spec 003): todo asiento exige una.
-- ---------------------------------------------------------------------------------------------
ON CONFLICT (code) DO NOTHING;

-- ---------------------------------------------------------------------------------------------
-- 4. Plan contable PCGE Perú Modificado 2019 (1192 cuentas)
-- ---------------------------------------------------------------------------------------------
-- Carga manual del plan PCGE Modificado 2019 y sus 1,192 cuentas.
-- Basado en sql/migrations/013_seed_pcge_modificado_2019.sql y en
-- data/accounting/pcge_modificado_2019.csv.
-- Requiere que las migraciones 012 y el esquema base ya estén aplicados,
-- y que public.users tenga al menos un usuario con role='ADMIN'.
-- Es transaccional e idempotente para el catálogo. No modifica asientos.
-- Las naturalezas normales e imputabilidad son clasificación operativa inferida;
-- un contador debe validarlas antes de registrar operaciones reales.
DO $$
DECLARE admin_id BIGINT; target_plan_id BIGINT;
BEGIN
  SELECT id INTO admin_id FROM public.users WHERE role='ADMIN' ORDER BY id LIMIT 1;
  IF admin_id IS NULL THEN RAISE EXCEPTION 'An ADMIN user is required to seed the accounting plan'; END IF;
  VALUES ('PCGE_PE','Modificado 2019','PCGE Perú','PE','Ministerio de Economía y Finanzas del Perú',
    'https://www.mef.gob.pe/contenidos/conta_publ/documentac/PCGE_2019.pdf',DATE '2019-01-01','ACTIVE',FALSE,admin_id)
  ON CONFLICT (code,edition) DO NOTHING;
  SELECT id INTO target_plan_id FROM public.accounting_plans WHERE code='PCGE_PE' AND edition='Modificado 2019';
  UPDATE public.accounting_plans SET is_default=FALSE,updated_at=CURRENT_TIMESTAMP
    WHERE is_default IS TRUE AND status='ACTIVE' AND id<>target_plan_id;
  UPDATE public.accounting_plans SET status='ACTIVE',is_default=TRUE,updated_at=CURRENT_TIMESTAMP WHERE id=target_plan_id;
  IF NOT EXISTS (
    SELECT 1 FROM public.accounting_configuration_events
     WHERE entity_type='PLAN' AND entity_id=target_plan_id AND action='SEEDED'
       AND reason='Seed inicial MEF'
       AND new_state=jsonb_build_object('code','PCGE_PE','edition','Modificado 2019')
  ) THEN
    VALUES ('PLAN',target_plan_id,'SEEDED',admin_id,
            jsonb_build_object('code','PCGE_PE','edition','Modificado 2019'),'Seed inicial MEF');
  END IF;
END $$;
CREATE TEMP TABLE _pcge_seed(code VARCHAR(40) PRIMARY KEY,name VARCHAR(200) NOT NULL,parent_code VARCHAR(40),
  account_group VARCHAR(40),normal_balance VARCHAR(6),is_postable BOOLEAN NOT NULL) ON COMMIT DROP;
DO $$
DECLARE target_plan_id BIGINT;admin_id BIGINT;code_len INTEGER;
BEGIN
  SELECT id INTO target_plan_id FROM public.accounting_plans WHERE code='PCGE_PE' AND edition='Modificado 2019';
  SELECT id INTO admin_id FROM public.users WHERE role='ADMIN' ORDER BY id LIMIT 1;
  IF (SELECT count(*) FROM _pcge_seed)<>1192 THEN RAISE EXCEPTION 'PCGE seed row count is invalid'; END IF;
  IF EXISTS(SELECT 1 FROM _pcge_seed s LEFT JOIN _pcge_seed p ON p.code=s.parent_code WHERE s.parent_code IS NOT NULL AND p.code IS NULL)
    THEN RAISE EXCEPTION 'PCGE seed has missing parent references'; END IF;
  FOR code_len IN 2..5 LOOP
    SELECT target_plan_id,s.code,s.name,p.id,s.account_group,s.normal_balance,s.is_postable,'ACTIVE',DATE '2019-01-01',admin_id
      FROM _pcge_seed s LEFT JOIN public.accounting_accounts p ON p.plan_id=target_plan_id AND p.code=s.parent_code
     WHERE length(s.code)=code_len ORDER BY s.code
    ON CONFLICT(plan_id,code) DO NOTHING;
  END LOOP;
  IF (SELECT count(*) FROM public.accounting_accounts WHERE plan_id=target_plan_id)<1192
    THEN RAISE EXCEPTION 'PCGE seed did not load every account'; END IF;
END $$;

-- ---------------------------------------------------------------------------------------------
-- Verificación: detiene la carga si falta algo.
-- ---------------------------------------------------------------------------------------------
DO $$
DECLARE v_admins INTEGER; v_parts INTEGER; v_openings INTEGER; v_accounts INTEGER; v_categories INTEGER;
BEGIN
  SELECT count(*) INTO v_admins FROM public.users WHERE role = 'ADMIN' AND active;
  SELECT count(*) INTO v_parts FROM public.spare_parts;
  SELECT count(*) INTO v_openings FROM public.inventory_movements WHERE movement_type = 'OPENING_BALANCE';
  SELECT count(*) INTO v_accounts FROM public.accounting_accounts a
    JOIN public.accounting_plans p ON p.id = a.plan_id
   WHERE p.code = 'PCGE_PE' AND p.edition = 'Modificado 2019' AND p.is_default;
  SELECT count(*) INTO v_categories FROM public.accounting_categories
   WHERE active AND code IN ('SALE', 'SERVICE', 'PURCHASE', 'OPERATING_EXPENSE', 'ADJUSTMENT', 'OTHER');
  IF v_admins < 1 THEN RAISE EXCEPTION 'No hay una cuenta ADMIN activa.'; END IF;
  IF v_categories <> 6 THEN RAISE EXCEPTION 'Faltan categorías contables: hay % de 6.', v_categories; END IF;
  IF v_parts < 433 THEN RAISE EXCEPTION 'Se esperaban al menos 433 repuestos y hay %.', v_parts; END IF;
  IF v_openings < v_parts THEN RAISE EXCEPTION 'Hay repuestos sin saldo inicial.'; END IF;
  IF v_accounts <> 1192 THEN RAISE EXCEPTION 'El PCGE predeterminado debe tener 1192 cuentas y tiene %.', v_accounts; END IF;
  RAISE NOTICE 'Datos iniciales listos: % ADMIN, % repuestos, % categorías contables, % cuentas PCGE.', v_admins, v_parts, v_categories, v_accounts;
END $$;

COMMIT;
